package dev.kubejseditor.verification;

import com.google.gson.*;
import dev.kubejseditor.client.*;
import dev.kubejseditor.model.*;
import dev.kubejseditor.recipe.*;
import dev.kubejseditor.recipe.compat.*;
import dev.kubejseditor.runtime.*;
import dev.kubejseditor.storage.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import java.nio.file.*;
import java.util.*;

/** One isolated client combines real mapping persistence/UI checks with the existing batch regression. */
@EventBusSubscriber(modid="kubejs_editor_verification",value=Dist.CLIENT)
public final class ClientUiRevisionVerification {
    private static int ticks,phase,checks;private static boolean completed;private static final JsonArray notes=new JsonArray();
    public static boolean finished(){return completed;}
    private static Minecraft mc(){return Minecraft.getInstance();}
    private static Path root(){return mc().gameDirectory.toPath();}
    private static void check(boolean value,String note){checks++;notes.add(note);if(!value)throw new AssertionError(note);}
    private static Object field(Object object,String name)throws Exception{var f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
    private static List<String> labels(){return mc().screen.children().stream().filter(c->c instanceof Button).map(c->((Button)c).getMessage().getString().replace("● ","")).toList();}
    private static void click(String label){var screen=mc().screen;var button=screen.children().stream().filter(c->c instanceof Button b&&b.getMessage().getString().replace("● ","").equals(label)).map(c->(Button)c).findFirst().orElseThrow(()->new AssertionError("Missing button: "+label+" in "+screen.getClass().getSimpleName()));check(button.active,"Enabled UI: "+label);screen.mouseClicked(button.getX()+2,button.getY()+2,0);screen.mouseReleased(button.getX()+2,button.getY()+2,0);}
    private static RecipePresentation presentation()throws Exception{return (RecipePresentation)field(mc().screen,"presentation");}
    private static CompatDefinition mapping()throws Exception{return (CompatDefinition)field(mc().screen,"definition");}
    private static void geometry(){var screen=mc().screen;for(var child:screen.children())if(child instanceof Button button)check(button.getX()>=0&&button.getY()>=0&&button.getX()+button.getWidth()<=screen.width&&button.getY()+button.getHeight()<=screen.height,"Mapping button remains within GUI bounds: "+button.getMessage().getString());}
    private static void reopen(String id)throws Exception{CompatibilityRecipes.load(root().resolve("mapping-cache-reset"));CompatibilityRecipes.load(root());CompatibilityScreenOpen.open(new WorkspaceScreen(),id);check(mc().screen instanceof CompatibilityScreen,"Mapped draft reopens after reading preferences from disk");}
    private static void exercise()throws Exception{
        var original=WorkspaceState.copy(EditorRuntime.project(),EditorProject.class);var originalScale=mc().options.guiScale().get();long reloads=EditorRuntime.reloadRequests();
        check(SimpleRecipes.enabled(),"Compatibility is enabled despite a legacy false preference");check(Files.readString(root().resolve(SimpleRecipes.FILE)).contains("false"),"Retired preference file is preserved and no longer gates editing");
        var workspace=new WorkspaceScreen();mc().setScreen(workspace);var top=labels();check(top.subList(0,5).equals(List.of("新增功能","修改现有","机械动力","已有修改","强制兼容"))&&!top.contains("批量删除"),"Exactly five main tabs keep force compatibility last");click("已有修改");check(labels().containsAll(List.of("配方修改","物品注册","批量删除")),"Batch deletion is a child action of Applied changes");click("批量删除");check(mc().screen instanceof AppliedDeletionScreen,"Applied changes opens the existing batch workflow");mc().screen.onClose();check(mc().screen==workspace&&((Integer)field(workspace,"tab"))==4,"Closing batch deletion returns to its Applied changes parent");click("强制兼容");check(labels().containsAll(List.of("选择配方","使用说明","拖入机器"))&&labels().stream().noneMatch(s->s.contains("实验")||s.contains("关闭")),"Compatibility has no experimental on/off control");
        String id=new RegistryEntryTarget("forbidden_arcanus:hephaestus_forge/ritual","forbidden_arcanus:eternal_stella").id();CompatibilityScreenOpen.open(workspace,id);check(mc().screen instanceof CompatibilityScreen,"Native ritual opens through the same mapping editor");var screen=(CompatibilityScreen)mc().screen;var originalData=screen.draft.data.deepCopy();check(!screen.ghostTargets().isEmpty(),"Automatic native mappings initially provide direct drag targets");var view=(CompatJeiLayouts.View)field(screen,"view");@SuppressWarnings("unchecked") var regions=(List<CompatJeiLayouts.BoundRegion>)field(screen,"regions");var first=regions.getFirst();CompatJeiLayouts.mark(id,view,screen.draft.data,first.binding(),first.rect());check(CompatJeiLayouts.readProfile(id,view,screen.draft.data)!=null,"An existing manual position is available for reset verification");
        click("字段映射");check(mc().screen instanceof CompatMappingScreen,"Field mapping dialog opens");int originalFields=mapping().fields.size();check(originalFields>0,"Automatic fields are shown before manual cancellation");
        while(!mapping().fields.isEmpty())click("×");click("确认并保存映射");check(mc().screen instanceof CompatibilityScreen&&presentation().bindings().isEmpty(),"Removing the final field saves successfully without automatically restoring it");check(((CompatibilityScreen)mc().screen).ghostTargets().isEmpty(),"A saved empty mapping has no implicit drag bindings");check(((CompatibilityScreen)mc().screen).draft.data.equals(originalData),"Canceling all mappings leaves the entire native recipe JSON unchanged");var saved=EditorRuntime.project().recipes.get(id);check(saved.compatibility.get("type").getAsString().equals(saved.data.get("type").getAsString()),"Native ritual mapping metadata keeps its actual registry type");var stale=WorkspaceState.copy(saved,EditorProject.RecipeDraft.class);
        reopen(id);check(presentation().bindings().isEmpty(),"Empty mapping remains empty after reload/reopen and named semantic discovery");var policy=CompatibilityRecipes.policy(((CompatibilityScreen)mc().screen).draft.data.get("type").getAsString(),originalData);check(policy!=null&&!policy.automatic()&&policy.fields.isEmpty(),"Disk preference distinguishes a deliberately empty map from automatic mode");
        click("字段映射");click("重置映射");check(mapping().fields.size()>=originalFields,"Reset rereads native/schema/JEI information and restores automatic fields");click("确认并保存映射");screen=(CompatibilityScreen)mc().screen;check(!presentation().bindings().isEmpty()&&!screen.ghostTargets().isEmpty(),"Saving automatic reset restores direct JEI dragging");check(CompatJeiLayouts.readProfile(id,(CompatJeiLayouts.View)field(screen,"view"),screen.draft.data)==null,"Reset also removes stale manual layout bindings for this page");var automaticDraft=WorkspaceState.copy(screen.draft,EditorProject.RecipeDraft.class);EditorRuntime.project().recipes.put(id,stale);reopen(id);check(!presentation().bindings().isEmpty(),"Saved automatic policy overrides older embedded manual mapping metadata");EditorRuntime.project().recipes.put(id,automaticDraft);EditorRuntime.saveDraft();
        var mappingFile=root().resolve("kubejs/config/kubejs_editor/recipe-mappings.json");var beforeCancel=Files.readString(mappingFile);click("字段映射");click("清空映射");check(mapping().fields.isEmpty(),"Clear-all button removes all fields in one action");click("取消");check(Files.readString(mappingFile).equals(beforeCancel)&&!presentation().bindings().isEmpty(),"Canceling an unsaved clear keeps the active automatic mapping");
        for(int scale:List.of(2,3)){mc().options.guiScale().set(scale);mc().resizeDisplay();click("字段映射");geometry();click("取消");}
        click("字段映射");String removed=mapping().fields.getFirst().path;click("×");click("确认并保存映射");reopen(id);check(presentation().definition.fields.stream().noneMatch(f->f.path.equals(removed)),"Deleting one mapped field also survives reopening without automatic augmentation");click("字段映射");click("重置映射");click("确认并保存映射");
        var cooking=mc().getSingleplayerServer().getRecipeManager().getRecipes().stream().filter(h->Objects.toString(BuiltInRegistries.RECIPE_SERIALIZER.getKey(h.value().getSerializer())).equals("minecraft:smelting")).findFirst().orElseThrow();CompatibilityScreenOpen.open(workspace,cooking.id().toString());check(RecipeAdapters.get("minecraft:smelting") instanceof CompatibilityAdapter,"Inspecting an existing ordinary recipe can install a transient mapping adapter");check(!(RecipeAdapters.creation("minecraft:smelting") instanceof CompatibilityAdapter),"Transient import retains the original furnace authoring template");
        var fresh=new WorkspaceScreen();mc().setScreen(fresh);click("+配方");check(mc().screen instanceof ChoiceScreen,"New recipe menu still opens");@SuppressWarnings("unchecked") var choices=(List<ChoiceScreen.Choice>)field(mc().screen,"choices");check(choices.stream().noneMatch(c->c.text().contains("简单适配")||c.text().contains("通用适配")),"New recipe choices exclude all runtime simple/generic adapter entries");check(choices.stream().anyMatch(c->c.text().contains("熔炉")),"The real furnace entry remains available after existing-recipe mapping");
        EditorRuntime.project().recipes.clear();EditorRuntime.project().recipes.putAll(original.recipes);EditorRuntime.saveDraft();mc().options.guiScale().set(originalScale);mc().resizeDisplay();check(EditorRuntime.reloadRequests()==reloads&&EditorRuntime.state().activation==null,"Navigation and mapping preferences never apply or reload game content");
        var report=new JsonObject();report.addProperty("passed",true);report.addProperty("checks",checks);report.addProperty("screenshots",false);report.add("details",notes);Files.writeString(root().resolve("ui-revision.json"),ProjectStore.JSON.toJson(report));completed=true;phase=99;mc().setScreen(new WorkspaceScreen());ClientBatchVerification.startInWorld();
    }
    @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!Boolean.getBoolean("kubejs.editor.verifyUiRevision")||phase==99)return;ticks++;try{if(ticks>12000)throw new AssertionError("UI verification timeout");if(phase==0&&mc().screen instanceof TitleScreen&&ticks>60){mc().createWorldOpenFlows().openWorld("EditorVerification",()->{});phase=1;ticks=0;return;}if(phase==1&&mc().level!=null&&mc().player!=null&&WorkspaceJeiPlugin.runtime!=null&&ticks>180){phase=2;exercise();}}catch(Throwable error){error.printStackTrace();try{var report=new JsonObject();report.addProperty("passed",false);report.addProperty("checks",checks);report.add("details",notes);var text=new java.io.StringWriter();error.printStackTrace(new java.io.PrintWriter(text));report.addProperty("error",text.toString());Files.writeString(root().resolve("ui-revision.json"),ProjectStore.JSON.toJson(report));}catch(Exception write){write.printStackTrace();}phase=99;mc().stop();}}
    private ClientUiRevisionVerification(){}
}
